# REL module configuration (the module list itself is the `modules:` block of config.yml; the
# per-module splits/symbols/sym_map/rel.json under config/G4BE08/modules/<mod>/ are generated by
# tools/gen_rel_config.py). Edit unit boundaries and Matching status by hand.

# Unit boundaries per module: list of (unit name, first function[, source file under src/]). The debug
# build's Bio4.<mod>.sym has no per-object information, so a module is one unit "<mod>/<mod>.cpp"
# unless listed here. Data sections are attributed to units by the relocations from the unit's code
# (see the tool). A third element names a source shared by several modules (the same object is
# linked into each of them).
#
# Every st2_* module ends with the same st2.cpp object (__FILE__ "D:/Bio4/Prog/st2.cpp": set/setTbl
# register all stage-2 room Init/Main pairs in St2_data_tbl, then the SN REL entry points _prolog
# (ctors, setTbl), _epilog (dtors) and _unresolved (HALT)). st1_*/st4_0 have st1.cpp/st4.cpp the same way.
_ST2 = ("st2.cpp", "set", "st2/st2.cpp")
_ST1 = ("st1.cpp", "set", "st1/st1.cpp")
UNITS = {
    "st1_1": [("st1_1/st1_1.cpp", None), ("st1_1/" + _ST1[0], *_ST1[1:])],
    "st1_2": [("st1_2/st1_2.cpp", None), ("st1_2/" + _ST1[0], *_ST1[1:])],
    "st1_3": [("st1_3/st1_3.cpp", None), ("st1_3/" + _ST1[0], *_ST1[1:])],
    # st1_0: r100.cpp (village) with its cManager<cLight>/cUnit linkonce copies, r120.cpp (the cabin cutscene
    # rooms; its nameless cManager<cLight> block follows it), then st1.cpp
    "st1_0": [("st1_0/r100.cpp", None), ("st1_0/r120.cpp", "R120Init"), ("st1_0/" + _ST1[0], *_ST1[1:])],
    "st2_0": [("st2_0/st2_0.cpp", None), ("st2_0/" + _ST2[0], *_ST2[1:])],
    "st2_1": [("st2_1/st2_1.cpp", None), ("st2_1/" + _ST2[0], *_ST2[1:])],
    "st2_2": [("st2_2/st2_2.cpp", None), ("st2_2/" + _ST2[0], *_ST2[1:])],
    "st2_3": [("st2_3/st2_3.cpp", None), ("st2_3/" + _ST2[0], *_ST2[1:])],
    # r22c: room 2-2c (the shooting gallery)
    "st2_4": [("st2_4/r22c.cpp", "cEmWrap::cEmWrap"), ("st2_4/" + _ST2[0], *_ST2[1:])],
    # Debug tool modules: <tool>.cpp, then the tool library objects t_prim.cpp / t_util.cpp (the full
    # versions of the DOL's game/t_prim, game/t_util, which the DOL link dead-stripped), then the shared
    # tools.cpp (D:/Bio4/Prog/tools.cpp: _prolog runs the ctors and ToolsTask, which dispatches
    # DebugMenuSelected to the Tool* entry of every tool module). Each object that includes light.h
    # carries its own cManager<cLight> instantiations behind its code (see LINKONCE below).
    # tools.cpp is also the last object of t_camera/t_light/t_sce/t_event (same bytes); t_esp/Tools/t_id
    # have their linkonce orphan sections behind it and t_movie has other objects after it.
    "t_camera": [("t_camera/t_camera.cpp", None), ("t_camera/tools.cpp", "_prolog", "tools/tools.cpp")],
    "t_light": [("t_light/t_light.cpp", None), ("t_light/tools.cpp", "_prolog", "tools/tools.cpp")],
    "t_sce": [("t_sce/t_sce.cpp", None), ("t_sce/tools.cpp", "_prolog", "tools/tools.cpp")],
    "t_event": [("t_event/t_event.cpp", None), ("t_event/tools.cpp", "_prolog", "tools/tools.cpp")],
    "t_emlist": [
        ("t_emlist/t_emlist.cpp", None),
        ("t_emlist/t_prim.cpp", "TprimInitEnv2D3D", "tools/t_prim.cpp"),
        # t_util's header strings (map_obj.h/light.h/widget.h) and its .data (old_menu, the menu
        # statics) are not addressed by its code
        ("t_emlist/t_util.cpp", "TutilInitDefault", "tools/t_util.cpp", {".rodata": 0x14E0, ".data": 0x29FC}),
        ("t_emlist/tools.cpp", "_prolog", "tools/tools.cpp"),
    ],
}
# The 16 Ganado modules (em10..em20) are the same em10.cpp ("D:/Bio4/Prog/em10.cpp": cEm10 and its
# em10*/em1c* helpers, .text 0-0x43518 + 0x3B8 bytes of template instantiations, .rodata 0-0x1EC4,
# all of .data/.bss, byte-identical in every module), then two small per-enemy objects whose names
# are not in the binary: the entry file (_prolog: OSReport("em10 prolog Ok\n") in every module,
# EmInitFunc = EmXXInit, EmSetFunc = EmXXSet; _epilog, _unresolved) and EmXXInit/Set/WeaponSet.
# They must be separate objects: ngcld -r adds an input section's displacement to ADDR16/ADDR32
# fields that reference a global defined in the same object, and the original fields are 0.
# em1d/em1e/em1f/em20 include light.h in the tail (cManager<cLight> code the .sym skips after
# EmXXWeaponSet) and carry an unreferenced "D:/Bio4/Prog/light.h" string right after em10.cpp's
# .rodata, so the entry unit's .rodata start is pinned (4th element) at em10.cpp's end.
for _em in ["em10", "em11", "em12", "em13", "em14", "em15", "em16", "em17", "em19", "em1a", "em1b",
            "em1c", "em1d", "em1e", "em1f", "em20"]:
    UNITS[_em] = [
        (f"{_em}/em10.cpp", None, "em10/em10.cpp"),
        (f"{_em}/{_em}_prolog.cpp", "_prolog", None, {".rodata": 0x1EC4}),
        (f"{_em}/{_em}_set.cpp", f"Em{_em[2:]}Init"),
    ]

# Units whose compiled object replaces the split object in the REL link.
MATCHING = {
    "st1_0/st1.cpp": True,
    "st1_1/st1.cpp": True,
    "st1_2/st1.cpp": True,
    "st1_3/st1.cpp": True,
    "st2_0/st2.cpp": True,
    "st2_1/st2.cpp": True,
    "st2_2/st2.cpp": True,
    "st2_3/st2.cpp": True,
    "st2_4/st2.cpp": True,
    "t_emlist/t_prim.cpp": True,
    "t_emlist/t_util.cpp": True,
    "t_emlist/tools.cpp": True,
    "t_camera/tools.cpp": True,
    "t_light/tools.cpp": True,
    "t_sce/tools.cpp": True,
    "t_event/tools.cpp": True,
}
